GLOSSARY = [
 ("Tibb", "طب", "The Arabic and Urdu word for medicine. <i>Tibb-e-Unani</i> means Greek (Ionian) medicine, the full name of the Unani system."),
 ("Unani", "یونانی", "From <i>Yunan</i>, Greece. A system of medicine built on Greek foundations and developed by Persian and Arab physicians, now practised mainly in South Asia."),
 ("Hakeem (Hakim)", "حکیم", "Literally 'wise one'. A practitioner of Unani medicine. In India and Pakistan the title is used by registered practitioners of the system."),
 ("Mizaj", "مزاج", "Temperament: the overall balance of hot, cold, moist and dry qualities in a person, organ or medicine. See <a href=\"learn/four-temperaments-explained.html\">the four temperaments</a>."),
 ("Akhlat", "اخلاط", "The four humours: blood (dam), phlegm (balgham), yellow bile (safra) and black bile (sauda)."),
 ("Dam", "دم", "Blood, the humour described as hot and moist. A dominant dam gives the sanguine (damwi) temperament."),
 ("Balgham", "بلغم", "Phlegm, the humour described as cold and moist. Gives the phlegmatic (balghami) temperament."),
 ("Safra", "صفرا", "Yellow bile, described as hot and dry. Gives the choleric (safrawi) temperament."),
 ("Sauda", "سودا", "Black bile, described as cold and dry. Gives the melancholic (saudawi) temperament."),
 ("Arkan", "ارکان", "The four elements of classical theory: earth, water, air and fire."),
 ("Tabiyat", "طبیعت", "The body's own healing power (similar to the Latin <i>vis medicatrix naturae</i>), which treatment aims to support."),
 ("Su-e-Mizaj", "سوء مزاج", "Dystemperament: an imbalance of temperament, the classical explanation of illness."),
 ("Mu'tadil", "معتدل", "Balanced or moderate temperament."),
 ("Daraja", "درجہ", "Degree. Medicines are graded from first to fourth degree for how strongly hot, cold, moist or dry they are."),
 ("Asbab-e-Sitta Zarooriya", "اسباب ستہ ضروریہ", "The six essentials of health: air; food and drink; movement and rest; sleep and wakefulness; retention and elimination; and emotions."),
 ("Ajnas-e-Ashra", "اجناس عشرہ", "The ten signs a practitioner uses to judge temperament, including touch, build, hair, sleep and emotional disposition."),
 ("Nabz", "نبض", "Pulse. Pulse reading is a central diagnostic skill in Unani practice."),
 ("Ilaj bil Tadbeer", "علاج بالتدبیر", "Regimenal therapy: treatment through measures such as cupping, massage, exercise, baths and diet."),
 ("Ilaj bil Ghiza", "علاج بالغذا", "Dietotherapy: treatment through food."),
 ("Ilaj bil Dawa", "علاج بالدوا", "Pharmacotherapy: treatment with medicines, mostly plant-based."),
 ("Ilaj bil Yad", "علاج بالید", "Surgery (literally 'treatment by hand')."),
 ("Hijama", "حجامہ", "Cupping, a regimenal therapy. Wet cupping involves small cuts. See <a href=\"learn/hijama-cupping-what-to-know.html\">our guide</a>."),
 ("Dalak", "دلک", "Therapeutic massage."),
 ("Riyazat", "ریاضت", "Exercise."),
 ("Majoon", "معجون", "A semi-solid preparation of powdered herbs mixed with honey or sugar syrup."),
 ("Khamira", "خمیرہ", "A semi-solid confection, often whipped, used as a tonic."),
 ("Itrifal", "اطریفل", "A confection based on the three myrobalan fruits, including amla."),
 ("Arq", "عرق", "A distillate, made by distilling herbs in water."),
 ("Joshanda", "جوشاندہ", "A decoction made by boiling herbs in water; also the name of a popular cold remedy blend."),
 ("Khaisanda", "خیسانده", "An infusion made by soaking herbs in water."),
 ("Sharbat", "شربت", "A syrup."),
 ("Roghan", "روغن", "An oil, for example roghan badam (almond oil)."),
 ("Safoof", "سفوف", "A powder."),
 ("Habb", "حب", "A pill."),
 ("Mufarreh", "مفرح", "An exhilarant: a medicine traditionally used to lift the spirits, such as saffron."),
 ("Dawakhana", "دواخانہ", "A pharmacy where Unani medicines are prepared and sold."),
 ("Matab", "مطب", "A practitioner's clinic."),
 ("BUMS", "", "Bachelor of Unani Medicine and Surgery, the main professional degree in India, regulated by the National Commission for Indian System of Medicine (NCISM)."),
 ("CCRUM", "", "Central Council for Research in Unani Medicine, India's government research body for Unani."),
]

